#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32

__global__ void matmul_kernel_tiled(const float* A, const float* B, float* C, int N) {
    __shared__ float tile_A[TILE_DIM][TILE_DIM];
    __shared__ float tile_B[TILE_DIM][TILE_DIM];

    int row = blockIdx.y * TILE_DIM + threadIdx.y;
    int col = blockIdx.x * TILE_DIM + threadIdx.x;

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    float sum = 0.0f;
    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tiles into shared memory
        if (row < N && (t * TILE_DIM + tx) < N) {
            tile_A[ty][tx] = A[row * N + (t * TILE_DIM + tx)];
        } else {
            tile_A[ty][tx] = 0.0f;
        }

        if ((t * TILE_DIM + ty) < N && col < N) {
            tile_B[ty][tx] = B[(t * TILE_DIM + ty) * N + col];
        } else {
            tile_B[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product
        for (int k = 0; k < TILE_DIM; ++k) {
            sum += tile_A[ty][k] * tile_B[k][tx];
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

