    __shared__ float tile_A[TILE_DIM][TILE_DIM];
    __shared__ float tile_B[TILE_DIM][TILE_DIM];

    int block_row = blockIdx.y;
    int block_col = blockIdx.x;

    int thread_row = threadIdx.y;
    int thread_col = threadIdx.x;

    // Each thread computes a THREAD_WORK_ROWS x THREAD_WORK_COLS sub-matrix of C
    float C_sub[THREAD_WORK_ROWS][THREAD_WORK_COLS] = {{0.0f}};

    // Starting position of the thread's sub-matrix in C
    int C_start_row = block_row * TILE_DIM + thread_row * THREAD_WORK_ROWS;
    int C_start_col = block_col * TILE_DIM + thread_col * THREAD_WORK_COLS;

    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tiles into shared memory
        // Each thread now loads THREAD_WORK_ROWS * THREAD_WORK_COLS elements
        for (int i = 0; i < THREAD_WORK_ROWS; ++i) {
            for (int j = 0; j < THREAD_WORK_COLS; ++j) {
                int a_row = block_row * TILE_DIM + thread_row * THREAD_WORK_ROWS + i;
                int a_col = t * TILE_DIM + thread_col * THREAD_WORK_COLS + j;
                if (a_row < N && a_col < N) {
                    tile_A[thread_row * THREAD_WORK_ROWS + i][thread_col * THREAD_WORK_COLS + j] = A[a_row * N + a_col];
                } else {
                    tile_A[thread_row * THREAD_WORK_ROWS + i][thread_col * THREAD_WORK_COLS + j] = 0.0f;
                }

                int b_row = t * TILE_DIM + thread_row * THREAD_WORK_ROWS + i;
                int b_col = block_col * TILE_DIM + thread_col * THREAD_WORK_COLS + j;
                if (b_row < N && b_col < N) {
