                } else {
                    tile_B[thread_row * THREAD_WORK_ROWS + i][thread_col * THREAD_WORK_COLS + j] = 0.0f;
                }
            }
        }
        __syncthreads();

        // Compute partial dot product
        for (int k = 0; k < TILE_DIM; ++k) {
            for (int i = 0; i < THREAD_WORK_ROWS; ++i) {
